from kin import *
p0=np.array([.034,.06,.73])
def solve(pd,seed,weight=.05):
 def fun(q):
  r,t=fk(q);return np.r_[(r@p0+t-pd)*10,Rot.from_matrix(r).as_rotvec()*weight,(q-seed)*.02]
 fit=least_squares(fun,np.clip(seed,lo+.011,hi-.011),bounds=(lo+.01,hi-.01),max_nfev=300);return fit.x,fun(fit.x)
if __name__=='__main__':
 pd=np.array([.02,.52,.13]);opts=[]
 for i in range(60):
  seed=np.array([-1.571,1.2,0,1.4,0,1.485,1.308]) if i==0 else np.random.default_rng(i).uniform(lo*.8,hi*.8)
  q,e=solve(pd,seed);opts.append((np.linalg.norm(e[:6]),np.linalg.norm(q-np.array([-1.571,1.2,0,1.4,0,1.485,1.308])),q))
 opts.sort(key=lambda x:x[0]+.015*x[1]);
 for a in opts[:5]:print(a)
 np.save('/app/output/floorpos_q.npy',opts[0][2]);r,t=fk(opts[0][2]);print(r,r@p0+t)
